package com.gymmind.ai.application;
import com.gymmind.ai.domain.ContextSegment; import com.gymmind.knowledge.application.KnowledgeSearchService; import com.gymmind.shared.error.*; import com.gymmind.shared.security.CurrentActor; import java.util.*; import org.springframework.stereotype.Service;
@Service public class DefaultAiChatService implements AiChatService { private final KnowledgeSearchService search; private final ChatModelGateway model; private final AiMemoryService memory; public DefaultAiChatService(KnowledgeSearchService s,ChatModelGateway m){this(s,m,null);} public DefaultAiChatService(KnowledgeSearchService s,ChatModelGateway m,AiMemoryService memory){search=s;model=m;this.memory=memory;} public AiChatView chat(CurrentActor a,String session,String q){if(a==null||a.tenantId()==null||!a.hasPermission("ai:chat"))throw new BusinessException(ErrorCode.FORBIDDEN);if(session==null||session.isBlank()||q==null||q.isBlank())throw new BusinessException(ErrorCode.VALIDATION_FAILED);List<ContextSegment> c=search.search(a,q);if(c==null||c.isEmpty())return new AiChatView("没有找到足够可靠的知识依据，暂不提供确定性建议。",List.of(),List.of());String prompt=withProfile(q,a);String answer=model.complete(prompt,c);if(answer==null||answer.isBlank())answer="模型暂时不可用，请稍后重试。";var sources=c.stream().map(ContextSegment::id).filter(Objects::nonNull).distinct().toList();var citations=c.stream().filter(x->x.id()!=null).map(x->new SourceCitation(x.id(),x.documentId(),x.text())).distinct().toList();return new AiChatView(answer,sources,citations);} private String withProfile(String q,CurrentActor a){if(memory==null)return q;var profile=memory.context(a);if(profile==null||profile.isEmpty())return q;return q+"\n用户画像记忆："+profile.stream().map(e->e.key()+"="+e.value()).reduce((x,y)->x+"；" ).orElse("");} }
